import {Chart} from '@gravity-ui/charts';
import {LayoutCellsLarge, ChartLine, ChartColumn, ChartDonut, Database, Persons, Gear, CircleQuestion, Bell, Plus, Calendar, Check, Xmark, ChevronDown, ChevronRight, ArrowUpRight, ArrowDownToLine, ArrowsRotateRight, Sliders, Grip, Magnifier, Target, ShoppingBag, CircleCheck, Ellipsis} from '@gravity-ui/icons';
import './styles.css';

configure({lang: 'ru'});
DashKit.setSettings({gridLayout: {cols: 12, rowHeight: 10, margin: [16, 16], containerPadding: [0, 0], compactType: null}, isMobile: false});
const money = (n: number) => new Intl.NumberFormat('ru-RU', {maximumFractionDigits: 0}).format(n);
const icons = {revenue: ChartLine, orders: ShoppingBag, clients: Persons, average: ChartColumn, dynamics: ChartLine, sources: ChartDonut, products: ShoppingBag, goal: Target};
type Kind = keyof typeof icons;
const titles: Record<Kind, string> = {revenue: 'Выручка', orders: 'Заказы', clients: 'Новые клиенты', average: 'Средний чек', dynamics: 'Динамика выручки', sources: 'Источники продаж', products: 'Популярные товары', goal: 'Цель по выручке'};
const descriptions: Record<Kind, string> = {revenue: 'Общая выручка за выбранный период', orders: 'Количество оформленных заказов', clients: 'Клиенты, совершившие первую покупку', average: 'Средняя стоимость одного заказа', dynamics: 'Выручка в сравнении с прошлым периодом', sources: 'Распределение выручки по каналам продаж', products: 'Товары, которые приносят больше выручки', goal: 'Прогресс достижения месячной цели'};
const kinds = Object.keys(titles) as Kind[];
const initialConfig: Config = {salt: 'orbit', counter: 8, aliases: {}, connections: [], items: kinds.map((kind, i) => ({id: kind, type: 'orbit-widget', namespace: 'default', data: {kind}, orderId: i})), layout: kinds.map((kind, i) => ({i: kind, x: i < 4 ? i * 3 : i % 2 === 0 ? 0 : 8, y: i < 4 ? 0 : i < 6 ? 6 : 20, w: i < 4 ? 3 : i % 2 === 0 ? 8 : 4, h: i < 4 ? 6 : i < 6 ? 14 : 13}))};
