const DashboardContext = createContext({factor: 1, period: 'month', channel: 'all', editing: false, remove: (_id: string) => {}, duplicate: (_kind: Kind) => {}, expand: (_kind: Kind) => {}, showProducts: () => {}});
const seriesValues = [38, 44, 40, 37, 53, 47, 39, 42, 63, 70, 59, 54, 69, 62, 57, 82, 87, 75, 65, 72, 79, 91, 87, 80, 99, 106, 94, 103, 117, 111];
