  {name: 'Наушники Nothing Ear', sub: 'Электроника', qty: 148, price: 14900, color: 'lavender', initials: '◉'},
  {name: 'Рюкзак Daypack', sub: 'Аксессуары', qty: 126, price: 6400, color: 'peach', initials: '▥'},
  {name: 'Колонка Sound Mini', sub: 'Электроника', qty: 98, price: 8900, color: 'sage', initials: '▤'},
  {name: 'Термокружка Everyday', sub: 'Для дома', qty: 87, price: 2900, color: 'sand', initials: '◧'},
];
function Spark({index}: {index: number}) {return <div className={"'`spark spark-${index}`}><Chart data={{chart: {margin: {top: 4, right: 0, bottom: 0, left: 0}}, xAxis: {visible: false}, yAxis: [{visible: false}], legend: {enabled: false}, tooltip: {enabled: false}, series: {data: [{type: '"'area', name: '', color: index === 2 ? 'var(--g-color-text-utility)' : 'var(--g-color-base-brand)', opacity: 0.09, lineWidth: 1.6, data: seriesValues.filter((_, i) => i % 2 === 0).map((v, i) => ({x: i, y: v + Math.sin(i * (index + 1)) * 15}))}]}} /></div>}
function WidgetBody({kind}: {kind: Kind}) {
  const {factor, period, channel, showProducts} = useContext(DashboardContext);
  if (['revenue', 'orders', 'clients', 'average'].includes(kind)) {
    const index = kinds.indexOf(kind); const values = [money(2840650 * factor) + ' ₽', money(1284 * factor), money(856 * factor), money(2212 * (1 + (factor - 1) * 0.1)) + ' ₽'];
    return <div className=\"metric-content\"><Text variant=\"display-1\" className=\"metric-number\">{values[index]}</Text><Spark index={index}/><div className=\"metric-comparison\"><span className=\"positive\"><Icon data={ArrowUpRight} size={13}/>{['18,6', '12,8', '8,2', '5,1'][index]}%</span><span>к прошлому периоду</span></div></div>;
  }
