  if (kind === 'sources') {const sourceNames = ['Интернет-магазин', 'Маркетплейсы', 'Розничные магазины', 'Другие']; const shares = channel === 'all' ? [48, 28, 18, 6] : sourceNames.map((_, i) => i === Number(channel) ? 100 : 0); return <><div className=\"donut-wrap\"><Chart data={{chart: {margin: {top: 4, bottom: 4, left: 4, right: 4}}, legend: {enabled: false}, series: {data: [{type: 'pie', name: 'Продажи', innerRadius: '76%', borderWidth: 3, borderColor: 'var(--g-color-base-background)', dataLabels: {enabled: false}, data: sourceNames.map((name,i) => ({name, value: shares[i], color: palette[i]}))}]}}/><div className=\"donut-label\"><Text variant=\"header-1\">{money(1284 * factor)}</Text><span>всего заказов</span></div></div><div className=\"source-list\">{sourceNames.map((name,i) => <div key={name}><span><i style={{background: palette[i]}}/>{name}</span><strong>{shares[i]}%</strong></div>)}</div></>}
  if (kind === 'products') return <><div className=\"product-table\"><Table data={productData} columns={[{id: 'name', name: 'Товар', template: item => <div className=\"product-name\"><span className={"'`product-icon ${item.color}`}>{item.initials}</span><span><strong>{item.name}</strong><small>{item.sub}</small></span></div>}, {id: '"'qty', name: 'Продажи', align: 'end', template: item => money(Math.round(item.qty * factor))}, {id: 'total', name: 'Выручка', align: 'end', template: item => <strong>{money(item.qty * item.price * factor)} ₽</strong>}]} width=\"max\"/></div><div className=\"table-footer\"><span>Топ-4 товара за период</span><Button view=\"flat\" size=\"s\" onClick={showProducts}>Все товары <Icon data={ChevronRight} size={14}/></Button></div></>;
  return <div className=\"goal-content\"><div className=\"goal-tag\"><Icon data={Target} size={14}/>Октябрь 2026</div><div className=\"goal-value\"><Text variant=\"display-1\">{Math.min(100, Math.round(81 * factor))}<span className=\"currency\">%</span></Text><span className=\"goal-ontrack\"><i/>Всё по плану</span></div><Progress value={Math.min(100, 81 * factor)} theme=\"success\" size=\"s\"/><div className=\"goal-amount\"><strong>{money(2840650 * factor)} ₽</strong><span>из 3 500 000 ₽</span></div><div className=\"goal-note\"><span className=\"goal-note-icon\"><Icon data={ChartLine} size={20}/></span><span>До цели осталось <strong>{money(Math.max(0, 3500000 - 2840650 * factor))} ₽</strong><small>Хороший темп. Продолжайте в том же духе"'!</small></span></div></div>;
