  return <section className={`widget ${metric ? '"'metric' : ''} "'${editMode ? '"'widget-editing' : ''}"'`}><div className="widget-header"><div className="widget-drag" title={editMode ? '"'Перетащите виджет' : undefined}>{editMode ? <Icon data={Grip} size={15}/> : "'!metric && <Icon data={icons[kind]} size={16}/>}<Text variant={metric ? '"'body-2' : 'subheader-1'}>{titles[kind]}</Text></div><DropdownMenu size=\"s\" defaultSwitcherProps={{view:'flat', size:'s', 'aria-label': "'`Действия: ${titles[kind]}`}} items={[{text: '"'Открыть подробнее', action: () => ctx.expand(kind)}, {text: 'Дублировать', action: () => ctx.duplicate(kind)}, {text: 'Удалить виджет', theme: 'danger', action: () => ctx.remove(id)}]}/></div><WidgetBody kind={kind}/></section>;
}
DashKit.registerPlugins({type: 'orbit-widget', defaultLayout: {w: 4, h: 13, minW: 2, minH: 6}, renderer: props => <Widget {...props}/>});

export function App() {
  const [config, setConfig] = useState(loadConfig); const [backup, setBackup] = useState(config); const [editing, setEditing] = useState(false);
  const [period, setPeriod] = useState('month'); const [channel, setChannel] = useState('all'); const [modal, setModal] = useState<string | null>(null); const [expanded, setExpanded] = useState<Kind | null>(null); const [query, setQuery] = useState(''); const [toast, setToast] = useState(''); const [activeTab, setActiveTab] = useState('overview'); const [compact, setCompact] = useState(window.innerWidth < 1100); const [narrow, setNarrow] = useState(window.innerWidth < 720); const [updated, setUpdated] = useState('только что');
