v>}<div className={"'`dashboard ${editing?'"'is-editing':''}"'`}><DashKit config={displayConfig} editMode={editing} noOverlay draggableHandleClassName="widget-drag" onChange={({config:next})=>{if(!narrow)setConfig(next);}}/>{config.items.length === 0 && <div className="empty-state"><Icon data={LayoutCellsLarge} size={42}/><Text variant="header-1">Место для ваших идей</Text><p>Добавьте первый виджет и соберите свой дашборд.</p><Button view="action" onClick={()=>setModal('"'library')}>Добавить виджет</Button></div>}</div><footer className=\"page-footer\"><span><i className=\"live-dot\"/>Данные обновлены {updated}<Button view=\"flat\" size=\"s\" aria-label=\"Обновить данные\" onClick={()=>{setUpdated(new Date().toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'}));setToast('Демонстрационные данные обновлены');}}><Icon data={ArrowsRotateRight} size={13}/></Button></span><span><Icon data={Grip} size={13}/>Ваш дашборд подстраивается под вас</span></footer></main></div>}/>
